const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const br = (s) => esc(s).replace(/\n/g, '<br>');
const w = $json.workflow || {};
const x = $json.execution || {};
const err = x.error || {};
const nombre = String(w.name || 'flujo de propuestas');
const esBorrador = /borrador/i.test(nombre);
const html = `<div style="margin:0;padding:24px 12px;background:#eef2f6;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:0 auto;background:#ffffff;border-radius:14px;overflow:hidden;box-shadow:0 2px 10px rgba(13,27,42,.08);">
<tr><td style="background:#0d1b2a;padding:18px 24px;">
<table role="presentation" cellpadding="0" cellspacing="0"><tr>
<td style="vertical-align:middle;"><img src="https://automatizatech.cl/wp-content/themes/automatiza-tech/assets/images/logo-automatiza-tech.png" width="44" height="37" alt="AutomatizaTech" style="display:block;border:0;"></td>
<td style="vertical-align:middle;padding-left:12px;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#ffffff;font-size:16px;font-weight:700;">AutomatizaTech<br><span style="color:#00d9c0;font-size:12px;font-weight:600;letter-spacing:.04em;">Propuestas · aviso interno</span></td>
</tr></table>
</td></tr>
<tr><td style="height:4px;background:#00d9c0;line-height:4px;font-size:0;">&nbsp;</td></tr>
<tr><td style="padding:26px 24px 8px;">
<span style="display:inline-block;background:#fee2e2;color:#991b1b;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:12px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;padding:5px 12px;border-radius:999px;">Error</span>
<h1 style="margin:14px 0 16px;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:22px;line-height:1.3;color:#0d1b2a;">Falló un flujo de propuestas: ${esc(nombre)}</h1>
${esBorrador ? `<div style="background:#fffbeb;border-left:4px solid #f59e0b;border-radius:8px;padding:14px 16px;margin:0 0 16px;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:14px;line-height:1.55;color:#334155;"><strong>Puede que una reunión no haya generado su borrador.</strong> La transcripción sigue en Drive › Transcripciones: para reintentar, vuelve a subirla (una copia) o pídemelo.</div>` : `<div style="background:#fffbeb;border-left:4px solid #f59e0b;border-radius:8px;padding:14px 16px;margin:0 0 16px;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:14px;line-height:1.55;color:#334155;"><strong>Si era una propuesta en «ajustando» o «generando», puede haber quedado trabada.</strong> Revísala en el panel de propuestas.</div>`}<p style="margin:0 0 14px;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:15px;line-height:1.55;color:#334155;"><strong>Qué falló</strong></p><div style="background:#fef2f2;border-left:4px solid #ef4444;border-radius:8px;padding:14px 16px;margin:0 0 16px;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:14px;line-height:1.55;color:#334155;">${esc(err.message || "Sin mensaje de error")}</div><p style="margin:18px 0 0;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:13px;line-height:1.5;color:#64748b;">Flujo: ${esc(nombre)} · paso: ${esc(x.lastNodeExecuted || "desconocido")} · ejecución de n8n: ${esc(x.id || "")}</p>
</td></tr>
<tr><td style="padding:14px 24px 22px;border-top:1px solid #e2e8f0;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:12px;line-height:1.5;color:#64748b;">
Aviso automático del flujo de propuestas de AutomatizaTech. Nada de esto se envía al cliente: el envío lo haces tú desde el panel.
</td></tr>
</table>
</div>`;
return [{ json: { asunto: '⚠️ Falló ' + nombre, html } }];
